{
  "sql": "SELECT COALESCE(t.product_category_name_english, 'sin_categoria') AS categoria, ROUND(SUM(f.freight_value) * 100.0 / SUM(f.price), 2) AS flete_porcentaje FROM vw_ingresos_por_categoria i INNER JOIN products p ON i.categoria_ingles = p.product_category_name LEFT JOIN product_category_translation t ON t.product_category_name = p.product_category_name WHERE i.ingresos >= 5000 GROUP BY categoria ORDER BY flete_porcentaje DESC LIMIT 3"
}
